grant select on public.post_media to anon;drop policy if exists post_media_read_visible on public.post_media;create policy post_media_read_visible on public.post_media for select to anon,authenticated using((exists(select 1 from public.user_posts p where p.id=post_id and p.visibility='public' and p.moderation_status='published' and ((p.profile_context='personal' and exists(select 1 from public.user_profiles up where up.id=p.user_id and up.visibility='public')) or (p.profile_context='professional' and exists(select 1 from public.professional_profiles pp where pp.id=p.professional_profile_id and pp.profile_status='active' and pp.visibility='public')) or (p.profile_context='business' and private.is_store_publicly_verified(p.business_store_id)))) or (auth.uid() is not null and exists(select 1 from public.user_posts p where p.id=post_id and p.user_id=auth.uid())));insert into public.post_media(post_id,user_id,media_path,media_type,position,duration_ms) select p.id,p.user_id,p.media_path,p.media_type,0,null from public.user_posts p where p.media_path is not null and p.media_type in('image','video') on conflict do nothing;create or replace function private.enforce_post_media_limit() returns trigger language plpgsql set search_path=pg_catalog,public as $$ declare n integer;begin if not exists(select 1 from public.user_posts p where p.id=new.post_id and p.user_id=(select auth.uid())) then raise exception 'Only post owner can add media';end if;select count(*) into n from public.post_media where post_id=new.post_id;if n>=15 then raise exception 'Maximum 15 media per post';end if;return new;end;$$;drop trigger if exists post_media_limit_guard on public.post_media;create trigger post_media_limit_guard before insert on public.post_media for each row execute function private.enforce_post_media_limit();revoke all on function private.enforce_post_media_limit() from public,anon,authenticated;